import sys
from math import gcd
from functools import reduce

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    r = int(data[0])
    c = int(data[1])

    if r == 1 and c == 1:
        print(0)
        return

    # Initialize the matrix
    matrix = [[0] * c for _ in range(r)]

    # Fill the matrix
    num = 1
    for i in range(r):
        for j in range(c):
            matrix[i][j] = num
            num += 1

    # Check if the matrix is diverse
    def is_diverse(matrix, r, c):
        row_gcds = [reduce(gcd, matrix[i]) for i in range(r)]
        col_gcds = [reduce(gcd, [matrix[i][j] for i in range(r)]) for j in range(c)]
        all_gcds = row_gcds + col_gcds
        return len(all_gcds) == len(set(all_gcds))

    # Adjust the matrix to make it diverse
    if not is_diverse(matrix, r, c):
        for i in range(r):
            for j in range(c):
                matrix[i][j] *= (r + c)

    # Print the matrix
    for row in matrix:
        print(" ".join(map(str, row)))

if __name__ == "__main__":
    main()
